<template>
  <div>

    <div v-if="loading" class="spinner-wrap">
      <div class="spinner"></div>
    </div>

    <div v-else-if="error" class="error-box">
      <p>{{ error }}</p>
      <button @click="fetchPost">Try again</button>
    </div>

    <div v-else-if="post">
      <h1 class="post-title">{{ post.title }}</h1>
      <p class="post-date">{{ formatDate(post.createdAt) }}</p>
      <div class="post-content">
        <p v-for="(para, index) in paragraphs" :key="index">{{ para }}</p>
      </div>
      <div class="back-links">
        <button class="back-btn" @click="$router.go(-1)">← Go back</button>
        <router-link to="/" class="back-btn">Home</router-link>
      </div>
    </div>

  </div>
</template>

<script>
import { ref, computed, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'

export default {
  name: 'PostDetailView',

  setup () {
    const route = useRoute()
    const router = useRouter()

    const post = ref(null)
    const loading = ref(true)
    const error = ref(null)

    async function fetchPost () {
      loading.value = true
      error.value = null

      try {
        const res = await fetch(`https://api.oluwasetemi.dev/posts/${route.params.id}`)
        if (res.status === 404) {
          router.replace('/404')
          return
        }
        if (!res.ok) throw new Error('Failed to load post. Status: ' + res.status)
        const json = await res.json()
        post.value = json.data || json
      } catch (err) {
        error.value = err.message
      } finally {
        loading.value = false
      }
    }

    const paragraphs = computed(() => {
      if (!post.value?.content) return []
      const sentences = post.value.content.match(/[^.!?]+[.!?]+\s*/g) || []
      const result = []
      for (let i = 0; i < sentences.length; i += 5) {
        result.push(sentences.slice(i, i + 5).join('').trim())
      }
      return result
    })

    function formatDate (dateStr) {
      if (!dateStr) return ''
      return new Date(dateStr).toLocaleDateString('en-GB', {
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      })
    }

    onMounted(() => fetchPost())

    return { post, loading, error, fetchPost, paragraphs, formatDate }
  }
}
</script>

